<script setup>
import { onMounted,onBeforeUnmount,ref,watch } from 'vue';
import { libraryRequest,jobRequest } from '../lib/library-client.js';
const apiOrigin=__API_ORIGIN__;
const props=defineProps({jobId:{type:String,default:''},initialBookId:{type:String,default:''},initialStatus:{type:String,default:''}}),verificationMode=__VERIFICATION_MODE__;
const books=ref([]),book=ref(''),jobs=ref([]),selected=ref(null),error=ref(''),pending=ref(false);
const retryPlan=ref(null),clearFaults=ref(false),retryRequestId=ref(crypto.randomUUID());
const kinds={verification:'Kiểm thử offline',tts:'Tạo giọng',translate:'Dịch',process:'Dịch rồi tạo giọng',merge:'Ghép audio',voice_sample:'Thử giọng'};
const labels={queued:'Đang chờ',running:'Đang chạy',completed:'Hoàn thành',failed:'Có lỗi',stop_requested:'Đang dừng an toàn',stopped:'Đã dừng',interrupted:'Bị gián đoạn — có thể tiếp tục'};
const filterBook=ref(props.initialBookId),filterStatus=ref(props.initialStatus),filterKind=ref(''),offset=ref(0),total=ref(0);
let timer,busy=false,refreshAgain=false;const requestId=ref(crypto.randomUUID());
async function refresh(){if(busy){refreshAgain=true;return;}busy=true;try{const query=new URLSearchParams({offset:offset.value,limit:20,book_id:filterBook.value,status:filterStatus.value,kind:filterKind.value});if(!filterBook.value)query.delete('book_id');const result=await jobRequest('?'+query);jobs.value=result.items;total.value=result.total;if(props.jobId)selected.value=await jobRequest('/'+props.jobId);error.value='';}catch(e){error.value=e.message;}finally{busy=false;if(refreshAgain){refreshAgain=false;refresh();}}}
async function create(){if(!book.value)return;pending.value=true;try{const result=await jobRequest('/verification',{book_id:book.value,request_id:requestId.value,steps:6,delay_ms:800});requestId.value=crypto.randomUUID();location.hash='jobs/'+result.id;await refresh();}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function previewRetry(){pending.value=true;error.value='';try{retryPlan.value=await jobRequest(`/${selected.value.id}/retry-plan`,{request_id:retryRequestId.value,clear_verification_faults:clearFaults.value});retryRequestId.value=crypto.randomUUID();}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function confirmRetry(){pending.value=true;try{const result=await libraryRequest(`/${retryPlan.value.id}/confirm`,{},'POST','job-plans');location.hash='jobs/'+result.id;}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function control(action){pending.value=true;try{await jobRequest(`/${selected.value.id}/${action}`,{});await refresh();}catch(e){error.value=e.message;}finally{pending.value=false;}}
watch(()=>[props.initialBookId,props.initialStatus],()=>{filterBook.value=props.initialBookId;filterStatus.value=props.initialStatus;offset.value=0;refresh();});
watch([filterBook,filterStatus,filterKind],()=>{offset.value=0;refresh();});
watch(()=>props.jobId,()=>{selected.value=null;retryPlan.value=null;retryRequestId.value=crypto.randomUUID();refresh();});
onMounted(async()=>{try{books.value=(await libraryRequest('?limit=100')).items;book.value=books.value[0]?.id||'';}catch(e){error.value=e.message;}await refresh();timer=setInterval(refresh,1000);});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template>
  <section class="mt-6 space-y-5">
    <div v-if="verificationMode" class="rounded-xl border border-line bg-surface p-5"><h2 class="text-base font-semibold">Job thử chạy nền</h2><p class="mt-2 text-xs leading-5 text-muted">6 bước, mỗi bước khoảng0,8giây; dùng provider giả lập và âm tone. Worker chạy riêng, không bị dừng khi chỉ tắt API.</p><div class="mt-4 flex flex-wrap items-end gap-3"><label for="job-book" class="grid min-w-0 gap-2 text-xs">Bộ truyện kiểm thử<select id="job-book" v-model="book" class="min-w-0 max-w-full rounded border border-line bg-canvas p-2"><option v-for="item in books" :key="item.id" :value="item.id">{{item.name}}</option></select></label><button id="create-test-job" :disabled="pending||!book" class="rounded-lg bg-brand px-4 py-2 text-sm text-brand-ink disabled:opacity-50" @click="create">Tạo job thử</button></div><a v-if="!books.length" href="#library" class="mt-3 inline-block text-xs text-brand underline">Tạo một bộ truyện trước</a></div>
    <p v-if="error" role="alert" id="jobs-error" class="rounded-lg border border-line bg-surface p-4 text-sm">{{error}}</p>
    <div class="rounded-xl border border-line bg-surface p-5"><div class="flex items-center justify-between"><h2 class="text-base font-semibold">Công việc gần đây</h2><button class="text-xs text-brand underline" @click="refresh">Kiểm tra lại</button></div><div class="mt-4 flex flex-wrap gap-3"><label class="grid gap-1 text-xs">Bộ truyện<select v-model="filterBook" class="max-w-full rounded border border-line bg-canvas p-2"><option value="">Tất cả</option><option v-for="item in books" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label class="grid gap-1 text-xs">Trạng thái<select v-model="filterStatus" class="rounded border border-line bg-canvas p-2"><option value="">Tất cả</option><option value="attention">Cần xử lý</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label class="grid gap-1 text-xs">Thao tác<select v-model="filterKind" class="rounded border border-line bg-canvas p-2"><option value="">Tất cả</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></label></div><p v-if="!jobs.length" class="mt-4 text-xs text-muted">Chưa có công việc.</p><ul class="mt-4 divide-y divide-line"><li v-for="job in jobs" :key="job.id" :data-job-id="job.id" :data-job-status="job.status" class="flex flex-wrap items-center justify-between gap-3 py-3"><a :href="`#jobs/${job.id}`" class="text-sm text-brand break-all">{{kinds[job.kind]||job.kind}} · {{job.id.slice(0,8)}}</a><span class="text-xs text-muted">{{labels[job.status]||job.status}}</span></li></ul><div class="mt-4 flex gap-4 text-xs"><button :disabled="offset===0" @click="offset-=20;refresh()">← Trước</button><span>{{total}} công việc · Trang {{Math.floor(offset/20)+1}}</span><button :disabled="offset+20>=total" @click="offset+=20;refresh()">Sau →</button></div></div>
    <article v-if="selected" id="job-details" class="rounded-xl border border-line bg-surface p-5"><h2 class="text-base font-semibold">{{labels[selected.status]||selected.status}}</h2><p class="mt-2 text-xs text-muted break-all">ID {{selected.id}}</p><div class="mt-4 flex flex-wrap gap-3"><button v-if="['queued','running'].includes(selected.status)" id="stop-job" :disabled="pending" class="rounded border border-line px-3 py-2 text-xs" @click="control('stop')">Dừng ở điểm an toàn</button><button v-if="['stopped','interrupted'].includes(selected.status)" id="resume-job" :disabled="pending" class="rounded-lg bg-brand px-3 py-2 text-xs text-brand-ink" @click="control('resume')">{{selected.kind==='translate'?'Tiếp tục — dịch lại toàn chương dở':'Tiếp tục từ checkpoint'}}</button><p v-if="selected.status==='stop_requested'" class="text-xs text-muted">Đã yêu cầu dừng; chờ provider kết thúc thao tác hiện tại. Chưa công bố file dở.</p></div><section v-if="['tts','translate','process'].includes(selected.kind)&&['failed','completed'].includes(selected.status)" class="mt-4 rounded-lg border border-line p-3"><h3 class="text-xs font-medium">{{selected.kind==='translate'?'Dịch lại toàn chương lỗi (có thể phát sinh lại chi phí)':'Retry phạm vi lỗi hoặc sửa audio hỏng'}}</h3><label v-if="verificationMode" class="mt-2 flex items-center gap-2 text-xs"><input id="clear-retry-faults" v-model="clearFaults" type="checkbox" />Bỏ lỗi giả lập trong kế hoạch retry mới</label><button id="preview-retry" :disabled="pending" class="mt-3 text-xs text-brand underline" @click="previewRetry">Xem kế hoạch retry</button><div v-if="retryPlan" id="retry-plan" class="mt-3"><p class="text-xs leading-5 text-muted">{{retryPlan.plan.notice}}</p><ul class="mt-2 text-xs"><li v-for="item in retryPlan.plan.chapters" :key="item.id">{{item.number}} · {{item.message}}</li></ul><p class="mt-2 text-xs">{{retryPlan.plan.chapters.length}} chương cần xử lý. {{selected.kind==='translate'?'Mỗi chương chưa hoàn tất sẽ dịch lại từ đầu.':'Các đoạn hợp lệ sẽ được giữ.'}}</p><button id="confirm-retry" :disabled="pending" class="mt-3 rounded-lg bg-brand px-3 py-2 text-xs text-brand-ink" @click="confirmRetry">Xác nhận retry</button></div></section><div v-if="selected.kind==='process'" id="process-stages" class="mt-4 space-y-2 text-xs"><p v-if="selected.active_stage">Đang ở bước: {{selected.active_stage==='translate'?'Dịch (tổng đoạn TTS xác định sau)':'TTS từ bản dịch đã lưu'}}</p><template v-if="selected.report?.translation"><p>Dịch: {{selected.report.translation.status}} · {{selected.report.translator_calls}} lần gọi</p><details v-if="selected.report.translation_sha256"><summary class="cursor-pointer text-brand">Đối chiếu bản dịch dùng cho audio</summary><p class="mt-2 break-all">ID {{selected.report.translation_artifact_id}} · SHA256 {{selected.report.translation_sha256}}</p></details><p>TTS: {{selected.report.tts?.status||'chưa chạy'}} · {{selected.report.tts_calls}} lần gọi</p></template></div><p id="job-progress" class="mt-4 text-sm">{{selected.completed_steps}} / {{selected.steps}} bước đã hoàn thành</p><progress class="mt-3 h-3 w-full" :value="(selected.kind==='process'&&selected.active_stage==='translate')||(selected.kind==='merge'&&selected.status==='running')?undefined:selected.completed_steps" :max="selected.steps||1"></progress><p v-if="selected.report" id="job-result" class="mt-4 text-xs leading-5 text-muted">{{selected.report.notice}}</p><div v-if="selected.report?.merged_artifact_id" id="merged-result" class="mt-4"><p class="text-xs">{{selected.report.duration.toFixed(2)}} giây · nguồn {{selected.report.input_duration.toFixed(2)}} giây · không gọi TTS</p><audio :key="selected.report.merged_artifact_id" id="merged-player" controls preload="metadata" :src="`${apiOrigin}/api/v1/books/${selected.book_id}/merged/${selected.report.merged_artifact_id}`" class="mt-3 max-w-full"></audio><a id="download-merged" :href="`${apiOrigin}/api/v1/books/${selected.book_id}/merged/${selected.report.merged_artifact_id}?download=true`" class="mt-3 inline-block text-xs text-brand underline">Tải MP3 ghép</a></div><div v-if="selected.report?.voice_artifact_id" id="voice-result" class="mt-4"><p class="text-xs">Mẫu thử lưu riêng · {{selected.report.duration.toFixed(2)}} giây</p><audio :key="selected.report.voice_artifact_id" id="voice-player" controls preload="metadata" :src="`${apiOrigin}/api/v1/books/${selected.book_id}/voice-samples/${selected.report.voice_artifact_id}`" class="mt-3 max-w-full"></audio><a :href="`${apiOrigin}/api/v1/books/${selected.book_id}/voice-samples/${selected.report.voice_artifact_id}?download=true`" class="mt-3 inline-block text-xs text-brand underline">Tải mẫu MP3</a></div><p v-if="selected.report?.provider_calls!==undefined" id="job-provider-calls" class="mt-3 text-xs">{{selected.report.provider_calls}} lần gọi provider · {{selected.status!=='completed'?'chưa hoàn thành':selected.kind==='process'?'theo các bước dịch/TTS':selected.kind==='translate'?(selected.report.reused?'giữ bản dịch':'đã dịch'):(selected.report.reused?'tái sử dụng audio':'đã tạo audio')}}</p><a v-if="['tts','translate','process','merge'].includes(selected.kind)&&selected.status==='completed'" :href="`#library/${selected.book_id}`" class="mt-3 inline-block text-xs text-brand underline">{{selected.kind==='translate'?'Mở truyện để xem và tải bản dịch →':'Mở truyện để nghe và tải audio →'}}</a><p v-if="selected.status==='running'" class="mt-3 text-xs text-muted">Có thể chuyển trang hoặc tải lại. Kết quả được lưu ở server.</p><p v-if="selected.report?.remaining_chapters" class="mt-3 text-xs">Chưa xử lý {{selected.report.remaining_chapters}} chương do chính sách dừng khi lỗi.</p><ul v-if="selected.report?.chapters" class="mt-4 space-y-2 text-xs"><li v-for="chapter in selected.report.chapters" :key="chapter.chapter_id">Chương {{chapter.number}} · {{chapter.status==='completed'?(chapter.reused?'giữ/tái sử dụng':'đã tạo'):'lỗi'}} · {{chapter.provider_calls}} lần gọi</li></ul><details class="mt-4"><summary class="cursor-pointer text-xs text-brand">Nhật ký các bước</summary><ol class="mt-3 space-y-2 text-xs text-muted"><li v-for="(event,index) in selected.events.filter(e=>['started','completed','failed'].includes(e.status))" :key="index">Bước {{event.chunk_index}} · {{event.status==='completed'?'xong':event.status==='started'?'bắt đầu':'lỗi'}}</li></ol></details><details v-if="selected.events.some(e=>e.glossary_hash)" id="translation-request-trace" class="mt-4"><summary class="cursor-pointer text-xs text-brand">Dấu vết model/prompt/glossary dùng thực tế</summary><ul class="mt-3 space-y-2 text-[10px] text-muted"><li v-for="(event,index) in selected.events.filter(e=>e.glossary_hash).slice(-6)" :key="index" class="break-all">Model {{event.model}} · Prompt {{event.prompt_hash}} · Glossary {{event.glossary_hash}}</li></ul></details></article>
  </section>
</template>
